{
  "technical_and_design_decisions": [
    "Target Java 17+ and Spring Framework 6.x / Spring Cloud Stream / Spring Data foundational abstractions.",
    "For U1: Build a custom KeyValue Spring Data repository backend integrating an off-heap state store (e.g., RocksDB or memory-mapped buffers) backed by Kafka changelog topics for restoration and state persistence.",
    "For U2 & U3: Implement an acknowledgment-aware flush controller that coordinates stream offset commits and state snapshotting based on module-producer message ACK events.",
    "For U4: Develop a Spring Integration / Stream CoAP inbound channel adapter wrapping Eclipse Californium to support resource observation and polling in resource-constrained environments.",
    "For U5: Produce AsciiDoc/Markdown reference documentation detailing deployment manifest properties schema, defaults, and examples.",
    "For U6: Enhance the Sqoop runner configuration to support Hadoop security (Kerberos authentication, keytab handling, and UserGroupInformation integration).",
    "For U7: Implement a Java REST client using WebClient/RestTemplate for Diego Receptor REST endpoints (Tasks, Desired/Actual LRPs) with proper serialization model.",
    "For U8: Refactor Boot-based ModuleRunner to parse, bind, and apply deployment properties directly to containerized Spring Boot module applications."
  ],
  "assumptions": [
    "Development and testing will be conducted by a single senior Java/Spring software developer.",
    "Standard CI/CD environments, test containers (Kafka, Secure Hadoop/Kerberos, CoAP mock server), and build tools are available.",
    "The scope of U8 is limited to finalizing remaining deployment property processing in ModuleRunner without requiring xd-containers runtime dependencies.",
    "Workdays represent 8 productive engineering hours."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Architecture & Technical Design",
      "activity_description": "Analyze requirements across all user stories (U1-U8), design domain models, API interfaces, module interactions, and finalize technical blueprints.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "U1: Kafka Changelog Spring Data Repository & Off-Heap Integration",
      "activity_description": "Implement Spring Data repository support backed by off-heap storage and Kafka changelog topic consumption/restoration for stateful stream processing.",
      "most_likely_effort": 6.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "U2 & U3: Intelligent Offset and State Flushing Control",
      "activity_description": "Design and build ACK-triggered offset and state flush handlers to synchronize stream offset commits with producer message delivery acknowledgments.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "U4: CoAP Source Module Development",
      "activity_description": "Implement the CoAP source module using Californium client library, supporting configurable URI endpoints, Observe requests, and message conversion.",
      "most_likely_effort": 4.5
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "U5: Manifest Properties Configuration Documentation",
      "activity_description": "Write comprehensive reference documentation and sample manifest property files for deployment configurations.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "U6: Secured HDFS Support for Sqoop Jobs",
      "activity_description": "Extend Sqoop execution components to handle Kerberos authentication, security context propagation, and secure HDFS cluster job submissions.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "U7: Diego Receptor Java REST Client",
      "activity_description": "Develop Java client library mapping Diego Receptor REST APIs including domain DTOs, HTTP request execution, error handling, and unit/mock tests.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "U8: Boot-based ModuleRunner Deployment Properties Completion",
      "activity_description": "Complete remaining deployment property binding, environment overrides, and configuration injection logic in Boot-based ModuleRunner for standalone containers.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "System Integration Testing and Quality Assurance",
      "activity_description": "Perform end-to-end integration testing across components, bug fixing, documentation polishing, and final release packaging.",
      "most_likely_effort": 3.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 36.0
  }
}
